import Model from 'flarum/common/Model';
export default class RewindSnapshot extends Model {
  year() {
    return Model.attribute('year').call(this);
  }
  snapshotData() {
    return Model.attribute('data').call(this);
  }
  generatedAt() {
    return Model.attribute('generatedAt', Model.transformDate).call(this);
  }
  isPublic() {
    return Model.attribute('isPublic').call(this);
  }
  canEdit() {
    return Model.attribute('canEdit').call(this);
  }
  canModerate() {
    return Model.attribute('canModerate').call(this);
  }
  isEmpty() {
    return Model.attribute('isEmpty').call(this);
  }
  user() {
    return Model.hasOne('user').call(this);
  }
}
flarum.reg.add('huseyinfiliz-rewind', 'common/models/RewindSnapshot', RewindSnapshot);